package wgmodern;
import net.minecraft.core.BlockPos;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.item.ItemStack;
public class CuttingMenu extends AbstractContainerMenu {
 public final CuttingTable.Tile tile;
 public CuttingMenu(int id,Inventory inv,BlockPos pos){super(Content.CUTTING_MENU.get(),id);tile=(CuttingTable.Tile)inv.player.level().getBlockEntity(pos);if(!inv.player.level().isClientSide)tile.changed();addSlot(new Slot(tile,0,42,24));for(int i=0;i<3;i++)addSlot(new Slot(tile,1+i,60+20*i,56){@Override public boolean mayPlace(ItemStack s){return tile.accepts(s);}});addSlot(new Slot(tile,4,118,24){@Override public boolean mayPlace(ItemStack s){return false;}@Override public void onTake(Player p,ItemStack s){tile.consume();super.onTake(p,s);}});for(int y=0;y<3;y++)for(int x=0;x<9;x++)addSlot(new Slot(inv,9+y*9+x,8+x*18,84+y*18));for(int x=0;x<9;x++)addSlot(new Slot(inv,x,8+x*18,142));addDataSlot(new DataSlot(){public int get(){return tile.cut;}public void set(int n){tile.cut=Math.floorMod(n,2);}});}
 @Override public void clicked(int slot,int button,ClickType type,Player p){if(!stillValid(p))return;if(!p.level().isClientSide)tile.changed();super.clicked(slot,button,type,p);}
 @Override public boolean stillValid(Player p){return tile.stillValid(p);}
 @Override public boolean clickMenuButton(Player p,int id){if(!stillValid(p)||(id!=0&&id!=1))return false;tile.cut=id;tile.changed();broadcastChanges();return true;}
 @Override public ItemStack quickMoveStack(Player p,int index){var slot=slots.get(index);if(!slot.hasItem())return ItemStack.EMPTY;var current=slot.getItem();var original=current.copy();if(index==4){int made=0;while(made<64&&!tile.getItem(4).isEmpty()){var result=tile.getItem(4).copy();if(!moveItemStackTo(result,5,41,true)||!result.isEmpty())break;tile.consume();made++;}return made>0?original:ItemStack.EMPTY;}if(index<4){if(!moveItemStackTo(current,5,41,true))return ItemStack.EMPTY;}else if(tile.accepts(current)){if(!moveItemStackTo(current,1,4,false))return ItemStack.EMPTY;}else if(!moveItemStackTo(current,0,1,false))return ItemStack.EMPTY;if(current.isEmpty())slot.set(ItemStack.EMPTY);else slot.setChanged();tile.changed();return original;}
}
